<?php
/** Procurement assistant block — research form, latest results with "Keep as alternative" / "Record price", saved alternatives (GAS-CP-R79-002).
 *  Expects $it (item or null), $back (url). */
$rs = stk_research_of($it['id'] ?? null, $it ? 6 : 12); $alts = $it ? stk_alternatives_of((int)$it['id']) : []; $can = stk_ai_can(); $cur = $it['currency'] ?? 'EUR';
$show = (int)($_GET['rs'] ?? 0); $open = $show ? array_values(array_filter($rs, fn($r) => (int)$r['id'] === $show)) : array_slice($rs, 0, 1); $open = $open[0] ?? null; $D = $open ? stk_research_data($open) : [];
$pm = fn($v, $c) => $v !== null && $v !== '' && is_numeric($v) ? number_format((float)$v, 2, ',', '.') . ' ' . ($c ?: 'EUR') : '—';
?>
<div class="card" id="research">
  <h2>✨ <?= tt('stk.ai_title') ?></h2>
  <p class="hint" style="margin-top:0;"><?= tt('stk.ai_hint') ?></p>
  <?php if (!$can): ?><p class="flash flash--warn"><?= tt('stk.ai_off') ?></p><?php elseif (pr_admin()): ?>
  <form method="post" action="<?= $back ?>" data-lock class="stk-ai-form"><?= csrf_field() ?><input type="hidden" name="action" value="stk_research"><input type="hidden" name="item_id" value="<?= (int)($it['id'] ?? 0) ?>">
    <?php if (!$it): ?><div class="field"><label><?= tt('stk.ai_part') ?> *</label><input name="query" required maxlength="400" placeholder="<?= tt('stk.ai_part_ph') ?>"></div><?php endif; ?>
    <div class="field"><label><?= $it ? tt('stk.ai_constraints') : tt('stk.ai_constraints2') ?></label><input name="constraints" maxlength="600" placeholder="<?= tt('stk.ai_constraints_ph') ?>"></div>
    <div class="btn-row"><button class="btn btn--gold btn--sm" type="submit" name="mode" value="alternatives">🔎 <?= tt('stk.ai_find') ?></button><button class="btn btn--ghost btn--sm" type="submit" name="mode" value="prices">💶 <?= tt('stk.ai_prices') ?></button><span class="hint"><?= tt('stk.ai_wait') ?></span></div>
  </form>
  <?php endif; ?>

  <?php if ($alts): ?>
  <h3 style="margin-top:12px;"><?= tt('stk.alts') ?> <span class="count"><?= count($alts) ?></span></h3>
  <div class="table-scroll"><table class="tbl"><thead><tr><th><?= tt('stk.maker') ?></th><th><?= tt('stk.alt_part') ?></th><th><?= tt('stk.desc') ?></th><th><?= tt('stk.match') ?></th><th class="num"><?= tt('stk.unit_price') ?></th><th><?= tt('th.status') ?></th><th></th></tr></thead><tbody>
    <?php foreach ($alts as $a): ?><tr class="<?= $a['status'] === 'rejected' ? 'is-retired' : '' ?>"><td><?= e($a['maker'] ?? '') ?></td><td class="mono"><?= $a['alt_item_id'] ? '<a href="' . url('inventory_item', ['id' => (int)$a['alt_item_id']]) . '">' . e($a['alt_code']) . '</a>' : e($a['part_no'] ?? '') ?></td><td><?= e($a['description'] ?? '') ?><?= $a['note'] ? '<br><span class="hint">' . e($a['note']) . '</span>' : '' ?><?= $a['source_url'] ? '<br><a class="hint" href="' . e($a['source_url']) . '" target="_blank" rel="noopener noreferrer">' . e(parse_url($a['source_url'], PHP_URL_HOST) ?: 'source') . ' ↗</a>' : '' ?></td><td><?= pill($a['match_kind'] === 'exact' ? 'green' : ($a['match_kind'] === 'equivalent' ? 'gold' : 'mute'), t('stk.m_' . $a['match_kind'])) ?></td><td class="num"><?= e($pm($a['price'], $a['currency'])) ?><?= $a['seller'] ? '<br><span class="hint">' . e($a['seller']) . '</span>' : '' ?></td><td><?= pill($a['status'] === 'approved' ? 'green' : ($a['status'] === 'rejected' ? 'bad' : 'mute'), t('stk.as_' . $a['status'])) ?></td>
      <td class="row-actions"><?php if (pr_admin()): ?><form method="post" action="<?= $back ?>" style="display:inline;"><?= csrf_field() ?><input type="hidden" name="action" value="stk_alt_status"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><input type="hidden" name="item_id" value="<?= (int)$it['id'] ?>"><?php if ($a['status'] !== 'approved'): ?><button class="btn btn--ghost btn--sm" name="status" value="approved" title="<?= tt('stk.as_approved') ?>">✓</button><?php endif; ?><?php if ($a['status'] !== 'rejected'): ?><button class="btn btn--ghost btn--sm" name="status" value="rejected" title="<?= tt('stk.as_rejected') ?>">✕</button><?php endif; ?><button class="btn btn--ghost btn--sm" name="status" value="delete" title="<?= tt('btn.delete') ?>">🗑</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
  <?php endif; ?>

  <?php if ($open): ?>
  <h3 style="margin-top:12px;"><?= $open['mode'] === 'prices' ? '💶 ' . tt('stk.ai_prices') : '🔎 ' . tt('stk.ai_find') ?> — <span class="hint" style="font-weight:400;"><?= e(fmt_datetime($open['created_at'])) ?> · <?= e($open['user_name'] ?? '') ?> · <?= e(t('stk.ai_meta', ['n' => (int)$open['searches'], 'c' => number_format((float)$open['cost_eur'], 2, ',', '.'), 's' => round((int)$open['ms'] / 1000)])) ?></span></h3>
  <?php if (!$it && $open['query']): ?><p><b><?= e($open['query']) ?></b></p><?php endif; ?>
  <?php if (!empty($D['part'])): $P = $D['part']; ?><p class="hint"><?= e(trim(($P['maker'] ?? '') . ' ' . ($P['part_no'] ?? ''))) ?><?= !empty($P['description']) ? ' — ' . e($P['description']) : '' ?><?= !empty($P['status']) ? ' · ' . pill($P['status'] === 'obsolete' ? 'bad' : ($P['status'] === 'active' ? 'green' : 'gold'), (string)$P['status']) : '' ?><?= !empty($P['key_specs']) ? '<br>' . e($P['key_specs']) : '' ?></p><?php endif; ?>
  <?php if (!empty($D['summary'])): ?><p class="flash flash--info" style="margin:6px 0;"><?= nl2br(e($D['summary'])) ?></p><?php endif; ?>
  <?php if ($open['mode'] === 'alternatives' && !empty($D['alternatives'])): ?>
  <div class="table-scroll"><table class="tbl"><thead><tr><th><?= tt('stk.maker') ?></th><th><?= tt('stk.alt_part') ?></th><th><?= tt('stk.desc') ?></th><th><?= tt('stk.match') ?></th><th><?= tt('stk.sources') ?></th><th></th></tr></thead><tbody>
    <?php foreach (array_slice($D['alternatives'], 0, 8) as $i => $a): $src = array_slice((array)($a['sources'] ?? []), 0, 4); $best = null; foreach ($src as $sr) if (isset($sr['price']) && is_numeric($sr['price']) && ($best === null || (float)$sr['price'] < (float)$best['price'])) $best = $sr; ?>
    <tr><td><?= e((string)($a['maker'] ?? '')) ?></td><td class="mono"><b><?= e((string)($a['part_no'] ?? '')) ?></b></td><td><?= e((string)($a['description'] ?? '')) ?><?= !empty($a['differences']) ? '<br><span class="hint">' . e((string)$a['differences']) . '</span>' : '' ?><?= !empty($a['approvals']) ? '<br><span class="hint">' . e((string)$a['approvals']) . '</span>' : '' ?></td><td><?= pill(($a['match'] ?? '') === 'exact' ? 'green' : (($a['match'] ?? '') === 'equivalent' ? 'gold' : 'mute'), t('stk.m_' . (in_array($a['match'] ?? '', ['exact', 'equivalent', 'functional'], true) ? $a['match'] : 'functional'))) ?></td>
      <td><?php foreach ($src as $sr): ?><div><?= !empty($sr['url']) && preg_match('#^https?://#i', (string)$sr['url']) ? '<a href="' . e((string)$sr['url']) . '" target="_blank" rel="noopener noreferrer">' . e((string)($sr['seller'] ?: parse_url((string)$sr['url'], PHP_URL_HOST))) . ' ↗</a>' : e((string)($sr['seller'] ?? '')) ?> <b><?= e($pm($sr['price'] ?? null, $sr['currency'] ?? 'EUR')) ?></b> <span class="hint"><?= e((string)($sr['availability'] ?? '')) ?></span></div><?php endforeach; ?></td>
      <td><?php if ($it && pr_admin()): ?><form method="post" action="<?= $back ?>"><?= csrf_field() ?><input type="hidden" name="action" value="stk_alt_add"><input type="hidden" name="item_id" value="<?= (int)$it['id'] ?>"><input type="hidden" name="research_id" value="<?= (int)$open['id'] ?>"><input type="hidden" name="maker" value="<?= e((string)($a['maker'] ?? '')) ?>"><input type="hidden" name="part_no" value="<?= e((string)($a['part_no'] ?? '')) ?>"><input type="hidden" name="description" value="<?= e((string)($a['description'] ?? '')) ?>"><input type="hidden" name="match" value="<?= e((string)($a['match'] ?? 'equivalent')) ?>"><input type="hidden" name="note" value="<?= e(trim((string)($a['differences'] ?? '') . ' ' . (string)($a['approvals'] ?? ''))) ?>"><input type="hidden" name="url" value="<?= e((string)($best['url'] ?? ($src[0]['url'] ?? ''))) ?>"><input type="hidden" name="price" value="<?= e((string)($best['price'] ?? '')) ?>"><input type="hidden" name="currency" value="<?= e((string)($best['currency'] ?? 'EUR')) ?>"><input type="hidden" name="seller" value="<?= e((string)($best['seller'] ?? '')) ?>"><button class="btn btn--ghost btn--sm" type="submit">+ <?= tt('stk.alt_keep') ?></button></form><?php endif; ?></td></tr>
    <?php endforeach; ?></tbody></table></div>
  <?php elseif ($open['mode'] === 'prices' && !empty($D['market'])): ?>
  <div class="table-scroll"><table class="tbl"><thead><tr><th><?= tt('stk.seller') ?></th><th class="num"><?= tt('stk.unit_price') ?></th><th><?= tt('stk.availability') ?></th><th><?= tt('pd.note') ?></th><th></th></tr></thead><tbody>
    <?php foreach (array_slice($D['market'], 0, 10) as $sr): ?><tr><td><?= !empty($sr['url']) && preg_match('#^https?://#i', (string)$sr['url']) ? '<a href="' . e((string)$sr['url']) . '" target="_blank" rel="noopener noreferrer">' . e((string)($sr['seller'] ?: parse_url((string)$sr['url'], PHP_URL_HOST))) . ' ↗</a>' : e((string)($sr['seller'] ?? '')) ?></td><td class="num"><b><?= e($pm($sr['price'] ?? null, $sr['currency'] ?? 'EUR')) ?></b><?= !empty($sr['moq']) ? '<br><span class="hint">MOQ ' . e((string)$sr['moq']) . '</span>' : '' ?></td><td class="hint"><?= e((string)($sr['availability'] ?? '')) ?></td><td class="hint"><?= e((string)($sr['note'] ?? '')) ?></td>
      <td><?php if ($it && pr_admin() && isset($sr['price']) && is_numeric($sr['price'])): ?><form method="post" action="<?= $back ?>"><?= csrf_field() ?><input type="hidden" name="action" value="stk_price_add"><input type="hidden" name="item_id" value="<?= (int)$it['id'] ?>"><input type="hidden" name="unit_price" value="<?= e((string)$sr['price']) ?>"><input type="hidden" name="priced_at" value="<?= date('Y-m-d') ?>"><input type="hidden" name="note" value="<?= e(mb_substr(t('stk.ai_market') . ' · ' . (string)($sr['seller'] ?? '') . ' · ' . (string)($sr['url'] ?? ''), 0, 160)) ?>"><button class="btn btn--ghost btn--sm" type="submit">+ <?= tt('stk.price_record') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
  <?php elseif (empty($D['summary'])): ?><p class="hint"><?= tt('stk.ai_nothing') ?></p><?php endif; ?>
  <?php endif; ?>
  <?php if (count($rs) > 1 || ($rs && !$it)): ?><p class="hint" style="margin-top:8px;"><?= tt('stk.ai_earlier') ?>: <?php foreach ($rs as $r): ?><a href="<?= url($it ? 'inventory_item' : 'inventory', ($it ? ['id' => (int)$it['id']] : ['tab' => 'research']) + ['rs' => (int)$r['id']]) ?>#research"<?= $open && (int)$r['id'] === (int)$open['id'] ? ' style="font-weight:700;"' : '' ?>><?= e(fmt_date($r['created_at'])) ?> <?= $r['mode'] === 'prices' ? '💶' : '🔎' ?><?= !$it ? ' ' . e(mb_substr($r['query'], 0, 40)) : '' ?></a> · <?php endforeach; ?></p><?php endif; ?>
</div>
